import{_ as o,o as t,c as i,a0 as a}from"./chunks/framework.BWpMpcZ2.js";const f=JSON.parse('{"title":"Workspaces","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/workspaces.md","filePath":"configuration/workspaces.md"}'),r={name:"configuration/workspaces.md"};function s(n,e,l,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="workspaces" tabindex="-1">Workspaces <a class="header-anchor" href="#workspaces" aria-label="Permalink to &quot;Workspaces&quot;">​</a></h1><p>A <strong>workspace</strong> is a folder on your computer holding your project — chapters, character sheets, style guides, world notes, <code>assets/</code>, <code>outputs/</code>. margin never moves your files; it just remembers which folder is active.</p><p>Settings live in <strong>Settings → Workspaces</strong> (previously under General). The gear icon opens Settings; use the search box to jump straight to &quot;workspace&quot;.</p><h2 id="profiles" tabindex="-1">Profiles <a class="header-anchor" href="#profiles" aria-label="Permalink to &quot;Profiles&quot;">​</a></h2><p>Every linked folder is remembered as a named <strong>profile</strong> (name + absolute path), newest first.</p><ul><li><strong>Open existing</strong> — Browse to a folder, confirm the name (defaults to the folder name), optionally tick Git init, and Link it. Re-linking a known folder updates its name and moves it to the front — never a duplicate.</li><li><strong>Create new</strong> — Pick a parent folder, type a single project-folder name, optionally tick Git init. margin scaffolds the folder only when it is new or empty (chapters, characters, manifest starter) and links it in one atomic step — a Git failure won&#39;t leave you pointing at a half-built directory.</li><li><strong>Rename / delete</strong> — Rename changes the display name only (your folder on disk is untouched). Deleting a profile just forgets it; your files stay on disk.</li><li><strong>Switch</strong> — Use the workspace switcher in the file sidebar header. The editor reloads from the newly linked folder.</li></ul><p>Profiles are stored in your platform config (<code>workspace_profiles</code> in <code>settings.json</code>) alongside <code>linked_workspace_dir</code> — never sent anywhere.</p><h2 id="sidebar-switcher-and-folder-ops" tabindex="-1">Sidebar switcher and folder ops <a class="header-anchor" href="#sidebar-switcher-and-folder-ops" aria-label="Permalink to &quot;Sidebar switcher and folder ops&quot;">​</a></h2><ul><li>The <strong>file sidebar header</strong> has a workspace switcher dropdown (active name + path) so you can jump between projects without opening Settings.</li><li>The sidebar file tree supports <strong>folder operations</strong>: new file/folder inline, rename, delete, with branch guides and folder icons. Layout (comfortable/compact) and sort are in the sidebar header dropdown.</li><li>Images you paste, drop, or generate are filed into the active workspace&#39;s <code>assets/</code> (<code>assets/generated/</code> for Imagine) and travel with it — see <a href="./images.html">Images</a>.</li></ul><h2 id="git-versioning-optional" tabindex="-1">Git versioning (optional) <a class="header-anchor" href="#git-versioning-optional" aria-label="Permalink to &quot;Git versioning (optional)&quot;">​</a></h2><p>Both Open and Create offer an <strong>Init Git</strong> toggle (only when Git is installed; default off — local-first).</p><ul><li>On Create, the repo is initialized as part of scaffolding.</li><li>On Open, Git init runs against the existing folder and reports partial success (linked, but Git failed) instead of failing the whole link.</li><li>margin never commits for you; the toggle only runs <code>git init</code> (+ initial commit on create when possible).</li></ul>',12)])])}const g=o(r,[["render",s]]);export{f as __pageData,g as default};
